#!/usr/bin/env node
/**
 * ULS Script Finder & Runner
 * 
 * Dynamically finds ULS installation (direct or nested) and executes a script
 * 
 * Usage:
 *   node scripts/find-uls.mjs <script-name> [command]
 * 
 * Examples:
 *   node scripts/find-uls.mjs uls.js init
 *   node scripts/find-uls.mjs update-config.mjs
 */

import { resolve } from 'path'
import { existsSync, readdirSync, lstatSync, readFileSync } from 'fs'
import { execSync } from 'child_process'

const projectRoot = process.cwd()
const nodeModulesPath = resolve(projectRoot, 'node_modules')

/**
 * Get script path based on script name and new organized structure
 */
function getScriptPath(ulsPath, scriptName) {
  // Map script names to their new locations in organized structure
  const scriptMap = {
    // CLI scripts
    'uls.js': resolve(ulsPath, 'src', 'scripts', 'cli', 'uls.js'),
    
    // Init scripts
    'create-init.js': resolve(ulsPath, 'src', 'scripts', 'init', 'create-init.js'),
    'update-config.mjs': resolve(ulsPath, 'src', 'scripts', 'init', 'update-config.mjs'),
    'create-passthrough.js': resolve(ulsPath, 'src', 'scripts', 'init', 'create-passthrough.js'),
    'create-override.js': resolve(ulsPath, 'src', 'scripts', 'init', 'create-override.js'),
    
    // Component scripts
    'create-component.js': resolve(ulsPath, 'src', 'scripts', 'components', 'create-component.js'),
    'delete-component.js': resolve(ulsPath, 'src', 'scripts', 'components', 'delete-component.js'),
    'create-uls-component.js': resolve(ulsPath, 'src', 'scripts', 'components', 'create-uls-component.js'),
    'create-uls-component-demo.mjs': resolve(ulsPath, 'src', 'scripts', 'components', 'create-uls-component-demo.mjs'),
    'create-custom-component-demo.mjs': resolve(ulsPath, 'src', 'scripts', 'components', 'create-custom-component-demo.mjs'),
    'create-custom-demo.mjs': resolve(ulsPath, 'src', 'scripts', 'components', 'create-custom-demo.mjs'),
    'create-custom-demo-type.mjs': resolve(ulsPath, 'src', 'scripts', 'components', 'create-custom-demo-type.mjs'),
    'register-uls-component-demo.mjs': resolve(ulsPath, 'src', 'scripts', 'components', 'register-uls-component-demo.mjs'),
    
    // Build scripts
    'uls-sync.js': resolve(ulsPath, 'src', 'scripts', 'build', 'uls-sync.js'),
    'purgecss-config.mjs': resolve(ulsPath, 'src', 'scripts', 'build', 'purgecss-config.mjs'),
    'uls-jit-generator.mjs': resolve(ulsPath, 'src', 'scripts', 'build', 'uls-jit-generator.mjs'),
    'diagnose-build.mjs': resolve(ulsPath, 'src', 'scripts', 'build', 'diagnose-build.mjs'),
  }
  
  // Check if script is in the map
  if (scriptMap[scriptName]) {
    return scriptMap[scriptName]
  }
  
  // Fallback: try old location (for backward compatibility)
  const oldPath = resolve(ulsPath, 'src', 'scripts', scriptName)
  if (existsSync(oldPath)) {
    return oldPath
  }
  
  // Try scripts folder (for find-uls.mjs itself)
  const scriptsPath = resolve(ulsPath, 'scripts', scriptName)
  if (existsSync(scriptsPath)) {
    return scriptsPath
  }
  
  return null
}

/**
 * Find ULS installation path (direct or nested)
 * @param {string} scriptName - Optional script name to verify exists
 */
function findULSPath(scriptName = null) {
  // 1. Check nested in UI packages first (for application repos)
  // This ensures we use the UI package's ULS version, not a direct installation
  if (existsSync(nodeModulesPath)) {
    try {
      const entries = readdirSync(nodeModulesPath, { withFileTypes: true })
      
      // Check regular packages (including symlinks)
      for (const entry of entries) {
        if (!entry.name.startsWith('@')) {
          const candidatePath = resolve(nodeModulesPath, entry.name)
          
          // Check if it's a directory or symlink by trying to access it
          let isAccessible = false
          try {
            const stats = lstatSync(candidatePath)
            isAccessible = stats.isDirectory() || stats.isSymbolicLink()
          } catch (err) {
            // Not accessible, skip
            continue
          }
          
          if (isAccessible) {
            const ulsPath = resolve(candidatePath, 'node_modules/uls-v2')
            
            if (existsSync(ulsPath)) {
              // If scriptName provided, verify script exists before returning
              if (scriptName) {
                const scriptPath = getScriptPath(ulsPath, scriptName)
                if (!scriptPath || !existsSync(scriptPath)) {
                  // Script doesn't exist in this nested location, continue searching
                  continue
                }
              }
              
              // If ULS exists in this package's node_modules, use it
              // (prioritize nested ULS over direct installation)
              return {
                ulsPath: ulsPath,
                isDirect: false,
                uiPackagePath: candidatePath
              }
            }
          }
        }
      }
      
      // Check scoped packages (@scope/package-name)
      const scopedDirs = entries.filter(e => e.isDirectory() && e.name.startsWith('@'))
      for (const scopedDir of scopedDirs) {
        const scopedPath = resolve(nodeModulesPath, scopedDir.name)
        try {
          const scopedEntries = readdirSync(scopedPath, { withFileTypes: true })
          for (const scopedEntry of scopedEntries) {
            if (scopedEntry.isDirectory()) {
              const candidatePath = resolve(scopedPath, scopedEntry.name)
              const ulsPath = resolve(candidatePath, 'node_modules/uls-v2')
              
              if (existsSync(ulsPath)) {
                try {
                    const pkgJsonPath = resolve(candidatePath, 'package.json')
                    if (existsSync(pkgJsonPath)) {
                      const pkgJson = JSON.parse(readFileSync(pkgJsonPath, 'utf8'))
                    const hasUls = 
                      (pkgJson.dependencies && pkgJson.dependencies['uls-v2']) ||
                      (pkgJson.devDependencies && pkgJson.devDependencies['uls-v2']) ||
                      (pkgJson.peerDependencies && pkgJson.peerDependencies['uls-v2'])
                    
                    if (hasUls) {
                      return {
                        ulsPath: ulsPath,
                        isDirect: false,
                        uiPackagePath: candidatePath
                      }
                    }
                  }
                } catch (err) {
                  // Continue searching
                }
              }
            }
          }
        } catch (err) {
          // Continue
        }
      }
    } catch (err) {
      // Continue
    }
  }
  
  // 2. Fallback: Check direct installation (for UI repos or direct installs)
  const directPath = resolve(nodeModulesPath, 'uls-v2')
  if (existsSync(directPath)) {
    // If scriptName provided, verify script exists before returning
    if (scriptName) {
      const scriptPath = getScriptPath(directPath, scriptName)
      if (!scriptPath || !existsSync(scriptPath)) {
        // Script doesn't exist in direct installation, return null to trigger nested fallback
        return null
      }
    }
    
    return {
      ulsPath: directPath,
      isDirect: true
    }
  }
  
  return null
}

/**
 * Find nested ULS (helper for fallback)
 */
function findNestedULS() {
  if (existsSync(nodeModulesPath)) {
    try {
      const entries = readdirSync(nodeModulesPath, { withFileTypes: true })
      for (const entry of entries) {
        if (!entry.name.startsWith('@')) {
          const candidatePath = resolve(nodeModulesPath, entry.name)
          try {
            const stats = lstatSync(candidatePath)
            if (stats.isDirectory() || stats.isSymbolicLink()) {
              const ulsPath = resolve(candidatePath, 'node_modules/uls-v2')
              if (existsSync(ulsPath)) {
                return {
                  ulsPath: ulsPath,
                  isDirect: false,
                  uiPackagePath: candidatePath
                }
              }
            }
          } catch (err) {
            continue
          }
        }
      }
    } catch (err) {
      // Continue
    }
  }
  return null
}

/**
 * Execute ULS script
 */
function executeScript(scriptName, command = '') {
  // Find ULS and verify script exists in one call
  const ulsInfo = findULSPath(scriptName)
  
  if (!ulsInfo) {
    console.error('⚠️  ULS not found. Make sure UI package is linked or uls-v2 is installed.')
    console.error('   Checked locations:')
    console.error(`   - ${resolve(nodeModulesPath, 'uls-v2')}`)
    console.error(`   - node_modules/*/node_modules/uls-v2`)
    process.exit(1)
  }
  
  // Get script path using new organized structure
  const scriptPath = getScriptPath(ulsInfo.ulsPath, scriptName)
  
  // Double-check script exists
  if (!scriptPath || !existsSync(scriptPath)) {
    console.error(`❌ Script not found: ${scriptName}`)
    console.error(`   ULS found at: ${ulsInfo.ulsPath}`)
    console.error(`   Looking for: ${scriptName}`)
    console.error(`   Tried path: ${scriptPath || 'unknown'}`)
    process.exit(1)
  }
  
  try {
    const args = command ? [scriptPath, ...command.split(' ')] : [scriptPath]
    execSync(`node ${args.join(' ')}`, { stdio: 'inherit', cwd: projectRoot })
  } catch (err) {
    console.error(`❌ Error executing script: ${err.message}`)
    process.exit(1)
  }
}

// Main
const scriptName = process.argv[2]
const command = process.argv.slice(3).join(' ')

if (!scriptName) {
  console.error('Usage: node scripts/find-uls.mjs <script-name> [command]')
  console.error('Example: node scripts/find-uls.mjs uls.js init')
  console.error('Example: node scripts/find-uls.mjs update-config.mjs')
  process.exit(1)
}

executeScript(scriptName, command)

